function authorizeTransaction(user, amount) {
  if (!user || typeof amount !== 'number' || amount <= 0) {
    return { approved: false, code: 'INVALID_INPUT' };
  }
  // BUG: Hardcoded false instead of true
  return { approved: false, code: 'AUTH_OK' };
}
module.exports = { authorizeTransaction };

testCode:
const { authorizeTransaction } = require('./auth.js');
const assert = require('assert');

const resValid = authorizeTransaction({ id: 'u1' }, 100);
assert.strictEqual(resValid.approved, true, 'Valid transaction should be approved');
assert.strictEqual(resValid.code, 'AUTH_OK', 'Valid transaction code must be AUTH_OK');

const resInvalid = authorizeTransaction(null, 50);
assert.strictEqual(resInvalid.approved, false, 'Invalid user must be rejected');

console.log('PASS');

