function averageScore(scores) {
  if (!scores) return 0;
  let sum = 0;
  for (let i = 0; i < scores.length; i++) {
    sum += scores[i];
  }
  // BUG: Divides by length - 1 causing off-by-one and division by zero
  return sum / (scores.length - 1);
}
module.exports = { averageScore };

testCode:
const { averageScore } = require('./average.js');
const assert = require('assert');

assert.strictEqual(averageScore([]), 0, 'Empty array must return 0');
assert.strictEqual(averageScore([10]), 10, 'Single element array must return that value');
assert.strictEqual(averageScore([10, 20, 30]), 20, 'Array [10, 20, 30] mean must be 20');
assert.strictEqual(averageScore(null), 0, 'Null input must return 0');

console.log('PASS');

