const assert = require('assert');

assert.strictEqual(compressString(""), "", 'Empty string must return empty string');
assert.strictEqual(compressString("A"), "1A", 'Single char should be 1A');
assert.strictEqual(compressString("AABBBCCCC"), "2A3B4C", 'Repeated characters must be compressed');
assert.strictEqual(compressString("ABBA"), "1A2B1A", 'Non-adjacent repeats must be preserved separately');

