const { generateHeader } = require('./header.js');
const assert = require('assert');

assert.strictEqual(API_VERSION, 'v2', 'API_VERSION must be updated to v2');
assert.strictEqual(generateHeader('/status'), 'Endpoint: /status | Version: v2');
assert.strictEqual(generateHeader('/users'), 'Endpoint: /users | Version: v2');

